const LEGACY_COMMAND_JUMP: u32 = 0;
pub const LEGACY_COMMAND_SYNC_FORWARD: u32 = 1;
const LEGACY_COMMAND_EXE_COMMAND: u32 = 3;
const LEGACY_COMMAND_REFETCH_TEMPLATE_FILES: u32 = 4;
const LEGACY_COMMAND_TEMP_SCENE: u32 = 6;
pub const LEGACY_COMMAND_FAST_PREVIEW_TIMEOUT: u32 = 9;

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct LegacySceneMsg {
    scene: String,
    sentence: u64,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct LegacyOutgoingEnvelope {
    event: String,
    data: LegacyOutgoingData,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct LegacyOutgoingData {
    command: u32,
    scene_msg: LegacySceneMsg,
    message: String,
    stage_sync_msg: Value,
}

#[derive(Debug, Deserialize)]
struct LegacyIncomingEnvelope {
    data: LegacyIncomingData,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct LegacyIncomingData {
    command: u32,
    scene_msg: LegacySceneMsg,
    message: String,
    stage_sync_msg: Value,
}

/// 旧版引擎发来的一条调试消息。
#[derive(Debug)]
pub struct LegacyMessage {
    pub command: u32,
    pub scene: String,
    pub sentence: u64,
    pub message: String,
    pub stage_sync_msg: Value,
}

fn parse_incoming_request_envelope(message: &str) -> Option<IncomingRequestEnvelope<Value>> {
    serde_json::from_str::<IncomingRequestEnvelope<Value>>(message).ok()
}

/// 将 V1 预览命令翻译为旧版引擎的调试 envelope (JSON 字符串)。
///
/// 返回 `None` 表示该命令无需/无法翻译给旧版引擎。
pub fn translate_preview_command_to_legacy(request: &str) -> Option<String> {
    let envelope = parse_incoming_request_envelope(request)?;
    if envelope.kind != "request" {
        return None;
    }

    let payload = envelope.payload;
    let (command, scene, sentence, message) = match envelope.message_type.as_str() {
        "preview.command.sync-scene" => (
            LEGACY_COMMAND_JUMP,
            payload.get("sceneName")?.as_str()?.to_string(),
            payload.get("sentenceId")?.as_u64()?,
            "Sync".to_string(),
        ),
        "preview.command.run-snippet" => (
            LEGACY_COMMAND_EXE_COMMAND,
            "temp".to_string(),
            0,
            payload.get("snippet")?.as_str()?.to_string(),
        ),
        "preview.command.run-scene-content" => (
            LEGACY_COMMAND_TEMP_SCENE,
            "temp".to_string(),
            0,
            payload.get("sceneContent")?.as_str()?.to_string(),
        ),
        "preview.command.reload-templates" => (
            LEGACY_COMMAND_REFETCH_TEMPLATE_FILES,
            "temp".to_string(),
            0,
            String::new(),
        ),
        _ => return None,
    };

    let envelope = LegacyOutgoingEnvelope {
        event: "message".to_string(),
        data: LegacyOutgoingData {
            command,
            scene_msg: LegacySceneMsg { scene, sentence },
            message,
            stage_sync_msg: Value::Object(serde_json::Map::new()),
        },
    };

    serde_json::to_string(&envelope).ok()
}

/// 解析旧版引擎发来的调试消息。
pub fn parse_legacy_message(message: &str) -> Option<LegacyMessage> {
    let envelope = serde_json::from_str::<LegacyIncomingEnvelope>(message).ok()?;
    Some(LegacyMessage {
        command: envelope.data.command,
        scene: envelope.data.scene_msg.scene,
        sentence: envelope.data.scene_msg.sentence,
        message: envelope.data.message,
        stage_sync_msg: envelope.data.stage_sync_msg,
    })
}
